package local.skyfamily;
import android.graphics.*;import android.os.*;import android.view.*;import java.util.*;
public class ArcadeBoard extends View {
 final ArcadeActivity host;final int mode;final Random rng=new Random();final Handler clock=new Handler();Paint p=new Paint(3);boolean active=false,paused=false,ended=false;String message="";int score=0;long last=0,step=0,power=0;int[][] maze=new int[15][15];boolean[][] dots=new boolean[15][15];int px=1,py=1,desired=1,current=1;int[][] ghosts={{13,13},{13,1},{1,13}};ArrayList<Integer> trace=new ArrayList<>();float touchX,touchY,oldX,oldY;
 int[][] board=new int[20][10];final int[][][] shapes={{{0,1},{1,1},{2,1},{3,1}},{{1,0},{2,0},{1,1},{2,1}},{{1,0},{0,1},{1,1},{2,1}},{{1,0},{2,0},{0,1},{1,1}},{{0,0},{1,0},{1,1},{2,1}},{{0,0},{0,1},{1,1},{2,1}},{{2,0},{0,1},{1,1},{2,1}}};int kind,nextKind,bx=3,by=0,lines=0;int[][] piece;ArrayList<Integer> bag=new ArrayList<>();float ballX=300,ballY=300,vx=230,vy=120,paddle=300,ai=300;int leftScore=0,rightScore=0;
 ArcadeBoard(ArcadeActivity h,int m){super(h);host=h;mode=m;setFocusable(true);if(m<2){generate(1,1);for(int y=1;y<14;y++)for(int x=1;x<14;x++)dots[y][x]=maze[y][x]==1;trace.add(16);dots[1][1]=false;}if(m==2){nextKind=take();spawn();}if(m==3)serve();}
 int take(){if(bag.isEmpty()){for(int i=0;i<7;i++)bag.add(i);Collections.shuffle(bag,rng);}return bag.remove(bag.size()-1);}
 void spawn(){kind=nextKind;nextKind=take();piece=new int[4][2];for(int i=0;i<4;i++)piece[i]=shapes[kind][i].clone();bx=3;by=0;if(!fits(piece,bx,by))finish("Game over");}
 void generate(int x,int y){maze[y][x]=1;ArrayList<Integer> directions=new ArrayList<>(Arrays.asList(0,1,2,3));Collections.shuffle(directions,rng);int[] dx={0,2,0,-2},dy={-2,0,2,0};for(int d:directions){int xx=x+dx[d],yy=y+dy[d];if(xx>0&&yy>0&&xx<14&&yy<14&&maze[yy][xx]==0){maze[y+dy[d]/2][x+dx[d]/2]=1;generate(xx,yy);}}}
 boolean open(int x,int y){return x>=0&&y>=0&&x<15&&y<15&&maze[y][x]==1;}
 void finish(String s){ended=true;message=s;int best=host.prefs.getInt("arcade.best."+mode,0);if(score>best)host.prefs.edit().putInt("arcade.best."+mode,score).apply();invalidate();}
 void start(){if(active)return;active=true;last=SystemClock.uptimeMillis();clock.post(loop);}
 void stop(){active=false;clock.removeCallbacksAndMessages(null);}
 final Runnable loop=new Runnable(){public void run(){if(!active)return;long now=SystemClock.uptimeMillis();float dt=Math.min(.05f,(now-last)/1000f);last=now;if(!paused&&!ended){if(mode==1&&now-step>170){step=now;chase(now);}if(mode==2&&now-step>Math.max(100,650-lines*15)){step=now;fall();}if(mode==3)pong(dt);}invalidate();clock.postDelayed(this,33);}};
 int[] dx={0,1,0,-1},dy={-1,0,1,0};
 void direction(int d){if(paused||ended)return;if(mode==0)traceTo(px+dx[d],py+dy[d]);if(mode==1)desired=d;if(mode==2){if(d==0)rotate();if(d==1&&fits(piece,bx+1,by))bx++;if(d==3&&fits(piece,bx-1,by))bx--;if(d==2){score++;fall();}}if(mode==3)paddle=Math.max(70,Math.min(530,paddle+(d==0?-30:d==2?30:0)));invalidate();}
 void traceTo(int x,int y){if(!open(x,y)||Math.abs(x-px)+Math.abs(y-py)!=1||ended)return;int cell=y*15+x;if(trace.size()>1&&trace.get(trace.size()-2)==cell)trace.remove(trace.size()-1);else if(!trace.contains(cell))trace.add(cell);else return;px=x;py=y;if(x==13&&y==13){score=1;finish("Maze complete!");}}
 boolean collide(long now){for(int[] ghost:ghosts)if(ghost[0]==px&&ghost[1]==py){if(now<power){score+=200;ghost[0]=13;ghost[1]=13;}else{finish("Caught / try again");return true;}}return false;}
 void chase(long now){if(open(px+dx[desired],py+dy[desired]))current=desired;if(open(px+dx[current],py+dy[current])){px+=dx[current];py+=dy[current];}if(dots[py][px]){dots[py][px]=false;score+=10;if((px==1||px==13)&&(py==1||py==13))power=now+6000;}if(collide(now))return;for(int[] ghost:ghosts){ArrayList<Integer> options=new ArrayList<>();for(int d=0;d<4;d++)if(open(ghost[0]+dx[d],ghost[1]+dy[d]))options.add(d);if(options.isEmpty())continue;Collections.shuffle(options,rng);int choice=options.get(0);if(rng.nextInt(100)<65){int best=now<power?-1:999;for(int d:options){int distance=Math.abs(ghost[0]+dx[d]-px)+Math.abs(ghost[1]+dy[d]-py);if(now<power?distance>best:distance<best){best=distance;choice=d;}}}ghost[0]+=dx[choice];ghost[1]+=dy[choice];}if(collide(now))return;for(boolean[] row:dots)for(boolean dot:row)if(dot)return;finish("All dots collected!");}
 boolean fits(int[][] shape,int x,int y){for(int[] cell:shape){int xx=x+cell[0],yy=y+cell[1];if(xx<0||xx>=10||yy<0||yy>=20||board[yy][xx]!=0)return false;}return true;}
 void rotate(){if(kind==1)return;int[][] rotated=new int[4][2];int edge=kind==0?3:2;for(int i=0;i<4;i++){rotated[i][0]=edge-piece[i][1];rotated[i][1]=piece[i][0];}for(int shift:new int[]{0,-1,1,-2,2})if(fits(rotated,bx+shift,by)){piece=rotated;bx+=shift;return;}}
 void fall(){if(ended)return;if(fits(piece,bx,by+1)){by++;return;}for(int[] cell:piece)board[by+cell[1]][bx+cell[0]]=kind+1;int cleared=0;for(int y=19;y>=0;y--){boolean full=true;for(int x=0;x<10;x++)if(board[y][x]==0)full=false;if(full){for(int row=y;row>0;row--)board[row]=board[row-1].clone();board[0]=new int[10];cleared++;y++;}}lines+=cleared;score+=100*cleared*cleared;spawn();}
 void drop(){if(mode!=2||paused||ended)return;while(fits(piece,bx,by+1)){by++;score+=2;}fall();invalidate();}
 void serve(){ballX=300;ballY=300;vx=rng.nextBoolean()?230:-230;vy=rng.nextInt(180)-90;}
 void pong(float dt){ai+=Math.max(-190*dt,Math.min(190*dt,ballY-ai));ai=Math.max(70,Math.min(530,ai));ballX+=vx*dt;ballY+=vy*dt;if(ballY<52){ballY=52;vy=Math.abs(vy);}if(ballY>548){ballY=548;vy=-Math.abs(vy);}if(vx<0&&ballX<45&&ballX>20&&Math.abs(ballY-paddle)<57){ballX=45;vx=Math.min(480,Math.abs(vx)*1.05f);vy=(ballY-paddle)*5;}if(vx>0&&ballX>555&&ballX<580&&Math.abs(ballY-ai)<57){ballX=555;vx=-Math.min(480,Math.abs(vx)*1.05f);vy=(ballY-ai)*5;}if(ballX<0){rightScore++;serve();}if(ballX>600){leftScore++;score++;serve();}if(leftScore>=7||rightScore>=7)finish(leftScore>=7?"You win!":"Computer wins");}
 int color(int i){int[] colors={0xff151f32,0xff73dfcc,0xffffcf92,0xffb8a5ff,0xfff2a4c6,0xff5a9dea,0xfff88c62,0xffa4d46b};return colors[i%colors.length];}
 void label(Canvas c,String s,float x,float y,int size,int color){p.setColor(color);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(size);p.setTextAlign(Paint.Align.LEFT);c.drawText(s,x,y,p);}
 protected void onDraw(Canvas c){c.save();c.scale(getWidth()/600f,getHeight()/600f);c.drawColor(0xff0b1120);if(mode<2){float cell=34,ox=45,oy=55;for(int y=0;y<15;y++)for(int x=0;x<15;x++){p.setColor(maze[y][x]==0?0xff294c71:0xff10192a);c.drawRect(ox+x*cell,oy+y*cell,ox+(x+1)*cell-1,oy+(y+1)*cell-1,p);if(mode==1&&dots[y][x]){p.setColor(0xffffcf92);c.drawCircle(ox+(x+.5f)*cell,oy+(y+.5f)*cell,(x==1||x==13)&&(y==1||y==13)?7:3,p);}}if(mode==0){p.setColor(0xff73dfcc);p.setStrokeWidth(9);p.setStrokeCap(Paint.Cap.ROUND);for(int i=1;i<trace.size();i++){int a=trace.get(i-1),b=trace.get(i);c.drawLine(ox+(a%15+.5f)*cell,oy+(a/15+.5f)*cell,ox+(b%15+.5f)*cell,oy+(b/15+.5f)*cell,p);}p.setColor(0xffffcf92);c.drawRect(ox+13*cell+5,oy+13*cell+5,ox+14*cell-5,oy+14*cell-5,p);}else{for(int i=0;i<ghosts.length;i++){p.setColor(SystemClock.uptimeMillis()<power?0xff5a9dea:color(i+3));c.drawRoundRect(new RectF(ox+ghosts[i][0]*cell+4,oy+ghosts[i][1]*cell+4,ox+(ghosts[i][0]+1)*cell-4,oy+(ghosts[i][1]+1)*cell-4),8,8,p);}}p.setColor(mode==0?0xff73dfcc:0xffffdf70);c.drawCircle(ox+(px+.5f)*cell,oy+(py+.5f)*cell,11,p);label(c,mode==0?"START  >  TRACE  >  END":"SCORE "+score,45,32,22,Color.WHITE);}if(mode==2){float ox=30,oy=15,s=28;for(int y=0;y<20;y++)for(int x=0;x<10;x++){p.setColor(color(board[y][x]));c.drawRect(ox+x*s,oy+y*s,ox+(x+1)*s-1,oy+(y+1)*s-1,p);}for(int[] a:piece){p.setColor(color(kind+1));c.drawRect(ox+(bx+a[0])*s,oy+(by+a[1])*s,ox+(bx+a[0]+1)*s-1,oy+(by+a[1]+1)*s-1,p);}label(c,"SCORE",350,60,23,Color.WHITE);label(c,String.valueOf(score),350,95,28,0xff73dfcc);label(c,"LINES "+lines,350,145,22,Color.WHITE);label(c,"NEXT",350,205,22,Color.WHITE);for(int[] a:shapes[nextKind]){p.setColor(color(nextKind+1));c.drawRect(350+a[0]*26,225+a[1]*26,373+a[0]*26,248+a[1]*26,p);}}if(mode==3){p.setColor(0xff294c71);p.setStrokeWidth(3);c.drawLine(300,45,300,555,p);p.setColor(0xff73dfcc);c.drawRect(25,paddle-50,40,paddle+50,p);p.setColor(0xfff2a4c6);c.drawRect(560,ai-50,575,ai+50,p);p.setColor(Color.WHITE);c.drawCircle(ballX,ballY,8,p);label(c,leftScore+" : "+rightScore,250,30,28,Color.WHITE);}if(paused||ended){p.setColor(0xdd0b1120);c.drawRect(30,235,570,345,p);label(c,paused?"PAUSED":message,55,295,27,Color.WHITE);}c.restore();}
 public boolean onTouchEvent(MotionEvent e){float x=e.getX()*600/getWidth(),y=e.getY()*600/getHeight();if(e.getAction()==0){touchX=x;touchY=y;oldX=x;oldY=y;getParent().requestDisallowInterceptTouchEvent(true);}if(!paused&&!ended){if(mode==3)paddle=Math.max(95,Math.min(505,y));if(mode==0){int samples=Math.max(1,(int)(Math.hypot(x-oldX,y-oldY)/8));for(int i=1;i<=samples;i++){float xx=oldX+(x-oldX)*i/samples,yy=oldY+(y-oldY)*i/samples;traceTo((int)Math.floor((xx-45)/34),(int)Math.floor((yy-55)/34));}oldX=x;oldY=y;}if(e.getAction()==1&&mode==1){float xx=x-touchX,yy=y-touchY;if(Math.abs(xx)+Math.abs(yy)>15)direction(Math.abs(xx)>Math.abs(yy)?xx>0?1:3:yy>0?2:0);}if(e.getAction()==1&&mode==2){float xx=x-touchX,yy=y-touchY;if(Math.abs(xx)+Math.abs(yy)<20)direction(0);else if(Math.abs(xx)>Math.abs(yy))direction(xx>0?1:3);else if(yy>40)drop();}}if(e.getAction()==1||e.getAction()==3)getParent().requestDisallowInterceptTouchEvent(false);invalidate();return true;}
 protected void onDetachedFromWindow(){stop();super.onDetachedFromWindow();}
}
